fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            let lines: Vec<String> = if keepends {
                s.split_terminator('\n') // Split by line terminators, keeping them
                    .map(|line| line.to_string() + "\n") // Append newline character
                    .collect()
            } else {
                s.split_terminator('\n') // Split by line terminators, not keeping them
                    .map(|line| line.to_string())
                    .collect()
            };

            // Ensure that the inner list is non-empty
            if lines.is_empty() {
                vec![String::new()] // Add a placeholder if no lines were found
            } else {
                lines
            }
        })
        .collect()
}